package com.supportsphere.dao; import com.supportsphere.exception.*; import com.supportsphere.util.*; import java.sql.*; import java.util.*;
public class AssignmentDAO {
 public void assign(int requestId,int volunteerId)throws Exception{try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);boolean committed=false;try{String status;int requester;try(PreparedStatement p=c.prepareStatement("SELECT status,requester_id,preferred_date,start_time,end_time,(CONCAT(preferred_date,' ',end_time)<NOW()) expired FROM assistance_requests WHERE request_id=? FOR UPDATE")){p.setInt(1,requestId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new AssignmentException("Request does not exist.");status=r.getString("status");requester=r.getInt("requester_id");if("OPEN".equals(status)&&r.getBoolean("expired")){expire(c,requestId,requester);c.commit();committed=true;throw new AssignmentException("This request has expired and cannot be accepted.");}}}if(!"OPEN".equals(status))throw new AssignmentException("This request has already been assigned or is no longer open.");validateAcceptance(c,requestId,volunteerId);try(PreparedStatement p=c.prepareStatement("INSERT INTO assignments(request_id,volunteer_id,accepted_at,status) VALUES(?,?,NOW(),'ASSIGNED')")){p.setInt(1,requestId);p.setInt(2,volunteerId);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("UPDATE assistance_requests SET status='ASSIGNED' WHERE request_id=?")){p.setInt(1,requestId);p.executeUpdate();}history(c,requestId,null,"ASSIGNED",volunteerId,"Volunteer accepted the request");notify(c,requester,"Volunteer assigned","Your request #"+requestId+" has been accepted.","ASSIGNMENT");c.commit();committed=true;}catch(Exception e){if(!committed)c.rollback();throw e;}}}
 public void start(int requestId,int volunteerId)throws Exception{transition(requestId,volunteerId,"IN_PROGRESS","UPDATE assignments SET status='IN_PROGRESS',started_at=NOW() WHERE request_id=? AND volunteer_id=?","Assistance started");}
 public void complete(int requestId,int volunteerId)throws Exception{transition(requestId,volunteerId,"COMPLETED","UPDATE assignments SET status='COMPLETED',completed_at=NOW() WHERE request_id=? AND volunteer_id=?","Assistance completed");}
 private void transition(int requestId,int volunteerId,String status,String sql,String msg)throws Exception{try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{int requester;try(PreparedStatement p=c.prepareStatement("SELECT requester_id,status FROM assistance_requests WHERE request_id=? FOR UPDATE")){p.setInt(1,requestId);try(ResultSet r=p.executeQuery()){if(!r.next()||!"ASSIGNED".equals(r.getString(2))&&!("COMPLETED".equals(status)&&"IN_PROGRESS".equals(r.getString(2)))&&!("IN_PROGRESS".equals(status)&&"ASSIGNED".equals(r.getString(2))))throw new AssignmentException("Invalid request state transition.");requester=r.getInt(1);}}try(PreparedStatement p=c.prepareStatement(sql)){p.setInt(1,requestId);p.setInt(2,volunteerId);if(p.executeUpdate()!=1)throw new AssignmentException("You are not assigned to this request.");}try(PreparedStatement p=c.prepareStatement("UPDATE assistance_requests SET status=? WHERE request_id=?")){p.setString(1,status);p.setInt(2,requestId);p.executeUpdate();}history(c,requestId,status.equals("IN_PROGRESS")?"ASSIGNED":"IN_PROGRESS",status,volunteerId,msg);notify(c,requester,msg,"Request #"+requestId+" — "+msg+".","STATUS");c.commit();}catch(Exception e){c.rollback();throw e;}}}
 public List<Map<String,Object>> forVolunteer(int id)throws Exception{return list("SELECT a.*,ar.task_type,ar.area,ar.city,ar.preferred_date,ar.start_time,ar.end_time,ar.urgency FROM assignments a JOIN assistance_requests ar ON ar.request_id=a.request_id WHERE a.volunteer_id=? ORDER BY a.assigned_at DESC",id);}
 private void validateAcceptance(Connection c,int requestId,int volunteerId)throws Exception{try(PreparedStatement lock=c.prepareStatement("SELECT volunteer_id FROM volunteer_profiles WHERE volunteer_id=? FOR UPDATE")){lock.setInt(1,volunteerId);try(ResultSet r=lock.executeQuery()){if(!r.next())throw new AssignmentException("Volunteer profile does not exist.");}}int active;try(PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM assignments WHERE volunteer_id=? AND status IN('ASSIGNED','IN_PROGRESS')")){p.setInt(1,volunteerId);try(ResultSet r=p.executeQuery()){r.next();active=r.getInt(1);}}if(active>=3)throw new AssignmentException("You have reached the limit of 3 active tasks.");try(PreparedStatement p=c.prepareStatement("SELECT preferred_date,start_time,end_time FROM assistance_requests WHERE request_id=? FOR UPDATE")){p.setInt(1,requestId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new AssignmentException("Request does not exist.");java.sql.Date preferredDate=r.getDate("preferred_date");Time startTime=r.getTime("start_time");Time endTime=r.getTime("end_time");if(preferredDate==null||startTime==null||endTime==null||!endTime.toLocalTime().isAfter(startTime.toLocalTime()))throw new AssignmentException("The request has an invalid schedule and cannot be accepted.");}}String q="SELECT 1 FROM assignments a JOIN assistance_requests ar ON ar.request_id=a.request_id JOIN assistance_requests nr ON nr.request_id=? WHERE a.volunteer_id=? AND a.status IN('ASSIGNED','IN_PROGRESS') AND ar.preferred_date=nr.preferred_date AND ar.start_time<nr.end_time AND nr.start_time<ar.end_time LIMIT 1";try(PreparedStatement p=c.prepareStatement(q)){p.setInt(1,requestId);p.setInt(2,volunteerId);try(ResultSet r=p.executeQuery()){if(r.next())throw new AssignmentException("This task overlaps with one of your active tasks.");}}}
 private static void expire(Connection c,int requestId,int requester)throws SQLException{try(PreparedStatement p=c.prepareStatement("UPDATE assistance_requests SET status='EXPIRED' WHERE request_id=? AND status='OPEN'")){p.setInt(1,requestId);p.executeUpdate();}history(c,requestId,"OPEN","EXPIRED",requester,"Request deadline passed");notify(c,requester,"Request expired","Your request #"+requestId+" expired because its scheduled time passed.","EXPIRATION");}
 public Optional<Integer> volunteerForRequest(int requestId)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT volunteer_id FROM assignments WHERE request_id=?")){p.setInt(1,requestId);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(r.getInt(1)):Optional.empty();}}}
 private List<Map<String,Object>> list(String q,Object...a)throws Exception{List<Map<String,Object>>x=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){for(int i=0;i<a.length;i++)p.setObject(i+1,a[i]);try(ResultSet r=p.executeQuery()){ResultSetMetaData m=r.getMetaData();while(r.next()){Map<String,Object>z=new LinkedHashMap<>();for(int i=1;i<=m.getColumnCount();i++)z.put(m.getColumnLabel(i),r.getObject(i));x.add(z);}}}return x;}
 private static void history(Connection c,int requestId,String oldStatus,String newStatus,int by,String note)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO request_history(request_id,old_status,new_status,changed_by,note) VALUES(?,?,?,?,?)")){p.setInt(1,requestId);p.setString(2,oldStatus);p.setString(3,newStatus);p.setInt(4,by);p.setString(5,note);p.executeUpdate();}}
 private static void notify(Connection c,int user,String title,String msg,String type)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO notifications(user_id,title,message,type) VALUES(?,?,?,?)")){p.setInt(1,user);p.setString(2,title);p.setString(3,msg);p.setString(4,type);p.executeUpdate();}}
}
